require_once __DIR__.'/../includes/bootstrap.php';require_role('Super Admin','College Admin');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['college_name','college_address','college_phone','college_email','attendance_threshold','passing_percentage','currency','timezone'] as $k){$v=trim($_POST[$k]??'');db()->prepare('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)')->execute([$k,$v]);}$_SESSION['flash']=['success','Settings saved'];redirect('settings.php');}$vals=[];foreach(db()->query('SELECT `key`,`value` FROM settings') as $r)$vals[$r['key']]=$r['value'];page_top('System Settings');flash();?><div class='card p-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><?php foreach(['college_name','college_address','college_phone','college_email','attendance_threshold','passing_percentage','currency','timezone'] as $k):?><div class='col-md-6'><label><?=e(ucwords(str_replace('_',' ',$k)))?></label><input class='form-control' name='<?=e($k)?>' value='<?=e($vals[$k]??'')?>'></div><?php endforeach;?><div class='col-12'><button class='btn btn-primary'>Save Settings</button></div></form></div><?php page_bottom();